package com.ecommerce.user_service.service;
import com.ecommerce.user_service.entity.FavoriteRestaurant;import com.ecommerce.user_service.repository.FavoriteRestaurantRepository;import java.util.Map;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service @Transactional(readOnly=true) public class FavoriteService{private final FavoriteRestaurantRepository repository;public FavoriteService(FavoriteRestaurantRepository r){repository=r;}public Map<String,Object> list(long userId){var rows=repository.findByUserIdOrderByCreatedAtDesc(userId).stream().map(f->Map.<String,Object>of("restaurantId",f.getRestaurantId(),"createdAt",f.getCreatedAt())).toList();return Map.of("content",rows,"totalElements",rows.size());}@Transactional public Map<String,Object> add(long uid,long restaurantId){if(restaurantId<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid restaurant id");var f=repository.findByUserIdAndRestaurantId(uid,restaurantId).orElseGet(()->repository.save(new FavoriteRestaurant(uid,restaurantId)));return Map.of("restaurantId",f.getRestaurantId(),"createdAt",f.getCreatedAt()==null?"":f.getCreatedAt().toString());}@Transactional public void remove(long uid,long restaurantId){repository.findByUserIdAndRestaurantId(uid,restaurantId).ifPresent(repository::delete);}}
